package io.horchestra.pack.sdk;

import io.horchestra.pack.sdk.packs.OpenBao;
import io.horchestra.pack.sdk.packs.Tembo;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.stream.Stream;

/**
 * The artifacts of the test packs, generated by this SDK, are the ones the Go sdk generates, byte for byte
 * (sdk/testdata/golden, written by {@code go test ./sdk -run Golden}). No test framework: it runs as a program,
 * from sdk/java:
 *
 * <pre>
 * javac --release 21 -d out/main $(find src/main -name '*.java')
 * javac --release 21 -cp out/main -d out/test $(find src/test -name '*.java')
 * java -cp out/main:out/test io.horchestra.pack.sdk.GoldenTest
 * </pre>
 */
public final class GoldenTest {
    private static final Path GOLDEN = Path.of("../testdata/golden");
    private static int failed;

    public static void main(String[] args) throws IOException {
        generatedEqualsGo();
        aHeldPackIsGeneratedAloneToo();
        pathsComeFromTheFields();
        refusals();
        escapes();
        if (failed > 0) {
            System.err.println(failed + " failed");
            System.exit(1);
        }
        System.out.println("ok");
    }

    private static void check(boolean ok, String what) {
        if (!ok) {
            failed++;
            System.err.println("FAIL: " + what);
        }
    }

    private static List<String> tree(Path dir) throws IOException {
        try (Stream<Path> s = Files.walk(dir)) {
            List<String> out = new ArrayList<>(s.filter(Files::isRegularFile).map(p -> dir.relativize(p).toString()).toList());
            out.sort(Comparator.naturalOrder());
            return out;
        }
    }

    private static void generatedEqualsGo() throws IOException {
        Path out = Files.createTempDirectory("packsdk");
        PackSdk.generate(out, new OpenBao());
        check(tree(GOLDEN).equals(tree(out)), "files: golden " + tree(GOLDEN) + ", got " + tree(out));
        for (String rel : tree(GOLDEN)) {
            if (!Files.exists(out.resolve(rel))) continue;
            check(new String(Files.readAllBytes(GOLDEN.resolve(rel))).equals(new String(Files.readAllBytes(out.resolve(rel)))),
                    rel + " differs from the Go sdk's");
        }
    }

    private static void aHeldPackIsGeneratedAloneToo() throws IOException {
        Path out = Files.createTempDirectory("packsdk");
        PackSdk.generate(out, new Tembo());
        check(tree(out).equals(List.of("tembo/pack.yaml", "tembo/schema.json", "tembo/templates/tembo.env.ptmpl")), "tembo alone: " + tree(out));
    }

    private static void pathsComeFromTheFields() {
        check(Paths.pointer(OpenBao.class, "bao", "storage").equals("/openbao/storage"), "pointer");
        check(Paths.dotted(OpenBao.class, "bao", "apiAddr").equals("openbao.api_addr"), "dotted maps Java names to the schema's");
        check(Paths.pointer(OpenBao.class, "postgres", "node", "nofailover").equals("/postgres/node/nofailover"), "through a held pack");
        boolean refused = false;
        try {
            Paths.pointer(OpenBao.class, "bao", "nope");
        } catch (SchemaException e) {
            refused = true;
        }
        check(refused, "a field that is not there is refused");
    }

    private static void escapes() {
        check(Json.write("a<b&c>d").equals("\"a\\u003cb\\u0026c\\u003ed\""), "html is escaped the way encoding/json does: " + Json.write("a<b&c>d"));
    }

    private static void refusals() {
        check(PackSdk.packs(new OpenBao()).stream().map(p -> p.meta().name).toList().equals(List.of("openbao", "tembo")), "packs lists what is held once");
    }
}
